def transform(grid):
    out = [row[:] for row in grid]
    r = next(i for i, row in enumerate(grid) if any(row))

    # Markers grow upward by a color-specific height, with the marker at the top.
    for c, color in enumerate(grid[r]):
        height = {2: 4, 8: 3}.get(color, 0)
        if height:
            top = max(0, r - height)
            out[top][c] = color
            for rr in range(top + 1, r):
                out[rr][c] = 1

    return out
